\end{equation*}
and with $x_{k}=\mu+\delta x_{k}$,
$\langle\delta x_{k}\rangle=0$,
$\langle\delta x_{k}\delta x_{l}\rangle=\sigma_{x}^{2}c_{kl}$,
$c_{kk}=1$,

\begin{equation*}
\big\langle\delta u_{k}\delta v_{k}\big\rangle
 =w\phi\sum_{l}s_{kl}\langle\delta x_{l}\delta x_{k}\rangle
 =w\phi\sigma_{x}^{2}\sum_{l}s_{kl}c_{kl}\; .
\end{equation*}
Mean field stationarity $\langle\dot w_{k}\rangle\propto\langle
u_{k}(v_{k}+\rho)\rangle=0$ is

\begin{equation*}
0=\langle u_{k}\rangle\langle v_{k}\rangle
   +\rho\langle u_{k}\rangle
   +\big\langle\delta u_{k}\delta v_{k}\big\rangle ,
\end{equation*}
i.e. up to the inessential $w\ne0$

\begin{equation*}
\phi\mu^{2}S_{k}+\rho\mu S_{k}
+\phi\sigma_{x}^{2}\sum_{l}s_{kl}c_{kl}=0\;,
\tag{1}
\end{equation*}
so that the DC gains $\langle v_{k}\rangle=\phi\mu$ and
$\langle u_{k}\rangle=w\mu S$ are $\tau_{v},\tau_{u}$ independent.
For translational invariance $c_{kl}=c$, $k\ne l$, $s_{kk}=1$,

\begin{equation*}
\sum_{l}s_{kl}c_{kl}=1+c\,(S_{k}-1) ,
\end{equation*}
and with $S_{k}\to S$ on the uniform manifold (1) is

\begin{equation*}
\phi\mu^{2}S+\rho\mu S+\phi\sigma_{x}^{2}\Big[\,1+c\,(S-1)\Big]=0,
\end{equation*}
i.e.

\begin{equation*}
1+c\,(S-1)=-
\frac{\mu\big(\phi\mu+\rho\big)}{\phi\sigma_{x}^{2}}\,S\; .
\end{equation*}
Hence the marginal stability point can be written in the canonical
form

\begin{equation*}
c^{*}(S)=\frac{\kappa S-1}{\,S-1\,},
\end{equation*}
with the mean-field control which multiplies $S$

\begin{equation*}
\kappa=
-\frac{\mu\big(\phi\mu+\rho\big)}{\phi\sigma_{x}^{2}}
=-\frac{\mu}{\sigma_{x}^{2}}\Big(\mu+\frac{\rho}{\phi}\Big),\qquad
c^{*}\to\kappa\;\;{\rm as}\;\;S\to\infty,
\end{equation*}
the $\tau_{v},\tau_{u}$ prefactors dropping out of the stationary
mean-field balance.  In the rate normalisation normally used
${\rm Cov}(x_{k},x_{l})=\mu^{2}c_{kl}$, $\sigma_{x}^{2}=\mu^{2}$,

\begin{equation*}
\kappa_{0}= -\frac{\phi\mu+\rho}{\phi\mu}
          =-1-\frac{\rho}{\phi\mu},\qquad
c^{*}(S)=\frac{\kappa_{0}S-1}{S-1},\qquad 
\lim_{S\to\infty}c^{*}=\kappa_{0},
\end{equation*}
so that up to the inessential overall sign $v_{k}\to v_{k}-\theta$,
$\rho\to-\theta$, the quantity normally quoted is

\begin{equation*}
\hat\kappa:=-\kappa_{0}
          =\frac{\phi\mu+\rho}{\phi\mu}
          =1+\frac{\rho}{\phi\mu}
          =1-\frac{\theta}{\phi\mu}\;,
\end{equation*}
i.e. $c^{*}=[\hat\kappa S-1]/(S-1)$ and $c^{*}\to\hat\kappa$ for
$S\to\infty$.  After the additive $-1$ is absorbed in the definition of
$S$ this is the familiar Hebbian-homeostatic ratio $|\rho|/\phi\mu$.
The $\tau_{u}\tau_{v}$ product does not survive the stated
$\langle\dot v\rangle=\langle\dot u\rangle=0$ steady state,
$v_{k}=\phi x_{k}$, $u_{k}=\sum_{l}s_{kl}w_{l}x_{l}$; it is recovered
only if the finite filter overlap $\int h_{v}h_{u}$ is kept explicit
and not absorbed in the normalisation of $c_{kl}$.  This is the
$1+\rho/\phi\mu\approx-\rho/\phi\mu$ control used by 1,2,3,5. ∎

